#!/usr/bin/env node
'use strict';

// Copy the sibling OpenCode plugin into this watchapp so a combined PBW can be built
// without the standalone plugin installed. The generated files are committed, so a clean
// clone can run `pebble build` without this script or the sibling checkout.
//
// Usage:
//   node scripts/sync-plugin.js [source-directory]
//   node scripts/sync-plugin.js [source-directory] --check
//
// The source defaults to ../oc-plugin. --check writes nothing and exits non-zero when a
// generated asset or the copied manifest block is stale.

const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.resolve(__dirname, '..');
const DEFAULT_SOURCE = path.resolve(ROOT, '..', 'oc-plugin');
const PLUGIN_SCRIPT = 'src/plugin/index.js';
const CONFIG_PAGE = 'src/config.html';
const BUNDLE_MARKER = 'globalThis.__ocStatusBundled = true;\n';
const GENERATED_NOTE = '<!-- Generated by scripts/sync-plugin.js from ../oc-plugin. Do not edit by hand. -->';
const DEFAULT_NOTIFICATION_REASON = 'To notify you when an OpenCode reply completes';
const LEGACY_REASON = 'To use the separately installed OpenCode plugin when the bundled copy is unavailable';

function fail(message) {
  console.error('sync-plugin: ' + message);
  process.exit(1);
}

function readText(file, label) {
  try {
    return fs.readFileSync(file, 'utf8');
  } catch (error) {
    fail('cannot read ' + label + ' (' + file + '): ' + error.message);
  }
}

function readJson(file, label) {
  const text = readText(file, label);
  try {
    return JSON.parse(text);
  } catch (error) {
    fail('invalid JSON in ' + label + ': ' + error.message);
  }
}

function projectFile(relative, label, root = ROOT) {
  if (typeof relative !== 'string' || !relative) fail(label + ' must be a project-relative path');
  const pure = relative.split(path.sep).join('/');
  if (path.isAbsolute(relative) || pure.split('/').includes('..') || relative.includes('\\') || relative.includes(':')) {
    fail(label + ' must stay inside the project: ' + relative);
  }
  return path.join(root, pure);
}

function isUuid(value) {
  return typeof value === 'string' &&
    /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(value);
}

function permissionName(permission) {
  return permission && typeof permission === 'object' ? permission.name : permission;
}

function clone(value) {
  return JSON.parse(JSON.stringify(value));
}

function copiedPermissions(targetPackage, sourcePackage) {
  const source = Array.isArray(sourcePackage.pebble.usesPermissions)
    ? sourcePackage.pebble.usesPermissions : [];
  const network = source.filter(permission => {
    const name = permissionName(permission);
    return name === 'Internet' || name === 'LocalNetwork';
  });
  if (!network.some(permission => permissionName(permission) === 'Internet')) network.unshift('Internet');
  if (!network.some(permission => permissionName(permission) === 'LocalNetwork')) network.push('LocalNetwork');

  const notifications = source.find(permission => permissionName(permission) === 'ShowNotifications') ||
    { name: 'ShowNotifications', reason: DEFAULT_NOTIFICATION_REASON, required: false };

  const legacyUuid = sourcePackage.pebble.uuid;
  const legacy = {
    name: 'InvokeAction',
    plugin: legacyUuid,
    reason: LEGACY_REASON,
    required: false
  };

  return [...network.map(clone), clone(notifications), legacy];
}

function injectStatusSettings(html) {
  if (!html.includes('</style>')) fail('plugin config page has no </style> to extend');
  if (!html.includes('<p id="feedback"')) fail('plugin config page has no #feedback anchor');
  if (!/\bid="replyAlerts"/.test(html)) fail('plugin config page has no reply notification toggle');
  if (!html.includes('</body>')) fail('plugin config page has no </body>');

  const css = `
    /* OC Status watch preferences, styled to match the shared OpenCode settings page. */
    .ocstatus-choices { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:10px; margin:0 0 14px; }
    .ocstatus-choice { display:flex; gap:11px; align-items:flex-start; min-height:64px; padding:13px 14px; border:1px solid var(--line); border-radius:11px; background:color-mix(in srgb,var(--wash) 35%,var(--panel)); cursor:pointer; -webkit-tap-highlight-color:transparent; touch-action:manipulation; }
    .ocstatus-choice:hover { border-color:color-mix(in srgb,var(--accent) 55%,var(--line)); }
    .ocstatus-choice:has(input:checked) { border-color:var(--accent); background:color-mix(in srgb,var(--accent) 9%,var(--panel)); box-shadow:0 0 0 1px color-mix(in srgb,var(--accent) 18%,transparent); }
    .ocstatus-choice:focus-within { outline:3px solid color-mix(in srgb,var(--accent) 48%,transparent); outline-offset:2px; }
    .ocstatus-choice input[type=radio], .ocstatus-choice input[type=checkbox] { width:19px; height:19px; flex:none; margin:3px 0 0; accent-color:var(--accent); }
    .ocstatus-choice span { display:block; min-width:0; }
    .ocstatus-choice strong { display:block; font-weight:620; line-height:1.3; }
    .ocstatus-choice small { display:block; margin-top:3px; color:var(--muted); font-size:.84rem; line-height:1.4; }
    .ocstatus-fieldset { border:0; padding:0; margin:0; min-width:0; }
    .ocstatus-subsection { margin-top:23px; }
    .ocstatus-subsection h3 { display:flex; align-items:center; gap:9px; margin:0 0 7px; font-size:1rem; line-height:1.3; letter-spacing:-.01em; }
    .ocstatus-subsection h3::before { width:3px; height:1.05em; flex:none; border-radius:8px; background:var(--accent); content:""; }
    .ocstatus-canned { min-height:118px; font-family:ui-monospace, "SFMono-Regular", Menlo, Consolas, monospace; }
    @media(max-width:620px) { .ocstatus-choices { grid-template-columns:minmax(0,1fr); gap:8px; } .ocstatus-choice { min-height:58px; padding:12px 13px; } }
  `;

  const section = `  <section id="ocstatusPreferences" class="card" aria-labelledby="ocstatusHeading">
    <h2 id="ocstatusHeading">Watch preferences</h2>
    <p class="hint">These settings apply to OpenCode Status on the watch. They are saved separately from the plugin connection and message settings above.</p>
    <fieldset id="ocstatusControls" class="ocstatus-fieldset" disabled>
      <div class="ocstatus-subsection">
        <h3>Plugin polling</h3>
        <p class="hint">Plugin default uses the OpenCode plugin's own refresh intervals.</p>
        <div class="ocstatus-choices">
          <label class="ocstatus-choice"><input type="radio" name="ocstatus_poll_rate" value="0"><span><strong>Plugin default</strong><small>Let the plugin decide when to refresh.</small></span></label>
          <label class="ocstatus-choice"><input type="radio" name="ocstatus_poll_rate" value="10"><span><strong>Every 10 seconds</strong><small>Fastest updates; uses more phone and network activity.</small></span></label>
          <label class="ocstatus-choice"><input type="radio" name="ocstatus_poll_rate" value="30"><span><strong>Every 30 seconds</strong><small>Balanced refresh rate.</small></span></label>
          <label class="ocstatus-choice"><input type="radio" name="ocstatus_poll_rate" value="60"><span><strong>Every 60 seconds</strong><small>Lowest activity.</small></span></label>
        </div>
      </div>
      <div class="ocstatus-subsection">
        <h3>Show only active or action-needed</h3>
        <p class="hint">Hides read or idle sessions. Running sessions, unread replies, questions, and permission requests stay visible.</p>
        <label class="ocstatus-choice"><input id="ocstatus_only_action" type="checkbox"><span><strong>Only show active or action-needed sessions</strong></span></label>
      </div>
      <div class="ocstatus-subsection">
        <h3>Mark read after</h3>
        <p class="hint">On app load, unread replies older than this are marked read automatically. Permission and question requests are never dismissed.</p>
        <div class="ocstatus-choices">
          <label class="ocstatus-choice"><input type="radio" name="ocstatus_mark_read_after" value="0"><span><strong>Never</strong><small>Leave unread dots alone until you clear them.</small></span></label>
          <label class="ocstatus-choice"><input type="radio" name="ocstatus_mark_read_after" value="300"><span><strong>5 minutes</strong></span></label>
          <label class="ocstatus-choice"><input type="radio" name="ocstatus_mark_read_after" value="900"><span><strong>15 minutes</strong></span></label>
          <label class="ocstatus-choice"><input type="radio" name="ocstatus_mark_read_after" value="1800"><span><strong>30 minutes</strong></span></label>
          <label class="ocstatus-choice"><input type="radio" name="ocstatus_mark_read_after" value="3600"><span><strong>1 hour</strong></span></label>
          <label class="ocstatus-choice"><input type="radio" name="ocstatus_mark_read_after" value="7200"><span><strong>2 hours</strong></span></label>
          <label class="ocstatus-choice"><input type="radio" name="ocstatus_mark_read_after" value="86400"><span><strong>1 day</strong></span></label>
        </div>
      </div>
      <div class="ocstatus-subsection">
        <h3>Subagents</h3>
        <p class="hint">Choose how subagents appear in the watch list.</p>
        <div class="ocstatus-choices">
          <label class="ocstatus-choice"><input type="radio" name="ocstatus_subagents" value="show"><span><strong>Show</strong><small>Show subagents as separate rows.</small></span></label>
          <label class="ocstatus-choice"><input type="radio" name="ocstatus_subagents" value="number"><span><strong>Number</strong><small>Hide child rows and count active descendants beside the parent indicator.</small></span></label>
          <label class="ocstatus-choice"><input type="radio" name="ocstatus_subagents" value="hide"><span><strong>Hide</strong><small>Hide child rows and counts.</small></span></label>
        </div>
        <p class="hint">Number and Hide also hide subagent questions and permission requests from the watch list. They are not forwarded to the parent session. Open OpenCode on your phone or computer to respond.</p>
        <p class="hint">Number requires an updated OpenCode plugin that exposes parent and root session IDs.</p>
      </div>
      <div class="ocstatus-subsection">
        <h3>Canned replies</h3>
        <p class="hint">One per line, up to 8. Short-press Select on a reply to choose one; long-press to dictate.</p>
        <textarea id="ocstatus_canned_replies" class="ocstatus-canned" spellcheck="true" placeholder="Continue&#10;Yes&#10;No"></textarea>
      </div>
    </fieldset>
    <div class="actions"><button class="primary" id="ocstatusSave" type="button" disabled>Save watch settings</button></div>
    <p id="ocstatusFeedback" class="hint" role="status" aria-live="polite"></p>
  </section>`;

  const statusScript = `<!-- ocstatus:settings-script -->
<script>
(() => {
  'use strict';
  const POLL_VALUES = [0, 10, 30, 60];
  const MARK_VALUES = [0, 300, 900, 1800, 3600, 7200, 86400];
  const SUBAGENT_VALUES = ['show', 'number', 'hide'];
  const state = { ready: false, loaded: false, saving: false };

  const $ = id => document.getElementById(id);

  function feedback(message, error = false) {
    const node = $('ocstatusFeedback');
    if (!node) return;
    node.textContent = message || '';
    node.classList.toggle('error', error);
    node.setAttribute('role', error ? 'alert' : 'status');
  }

  function setLoaded(loaded) {
    state.loaded = loaded;
    const controls = $('ocstatusControls');
    const save = $('ocstatusSave');
    if (controls) controls.disabled = !loaded;
    if (save) save.disabled = !loaded || state.saving;
  }

  function selectRadio(name, value) {
    const radios = document.querySelectorAll('input[name="' + name + '"]');
    let matched = false;
    Array.prototype.forEach.call(radios, radio => {
      const selected = String(radio.value) === String(value);
      radio.checked = selected;
      if (selected) matched = true;
    });
    if (!matched && radios.length) radios[0].checked = true;
  }

  function checkedValue(name, fallback) {
    const input = document.querySelector('input[name="' + name + '"]:checked');
    return input ? input.value : fallback;
  }

  function applySettings(settings) {
    if (!settings || typeof settings !== 'object' || Array.isArray(settings)) {
      throw new Error('OpenCode Status returned invalid watch settings.');
    }
    const rate = Number(settings.poll_rate);
    const mark = Number(settings.mark_read_after);
    const subagents = SUBAGENT_VALUES.indexOf(settings.subagents) === -1 ? 'show' : settings.subagents;
    selectRadio('ocstatus_poll_rate', POLL_VALUES.indexOf(rate) === -1 ? 0 : rate);
    selectRadio('ocstatus_mark_read_after', MARK_VALUES.indexOf(mark) === -1 ? 0 : mark);
    selectRadio('ocstatus_subagents', subagents);
    $('ocstatus_only_action').checked = !!settings.only_action;
    const canned = Array.isArray(settings.canned_replies) ? settings.canned_replies : [];
    $('ocstatus_canned_replies').value = canned.map(item => String(item)).join('\\n');
  }

  function collectSettings() {
    const poll = Number(checkedValue('ocstatus_poll_rate', '0'));
    const mark = Number(checkedValue('ocstatus_mark_read_after', '0'));
    const subagents = checkedValue('ocstatus_subagents', 'show');
    const canned = $('ocstatus_canned_replies').value.split(/\\r?\\n/)
      .map(line => line.trim())
      .filter(line => line.length > 0);
    return {
      poll_rate: POLL_VALUES.indexOf(poll) === -1 ? 0 : poll,
      only_action: $('ocstatus_only_action').checked ? 1 : 0,
      subagents: SUBAGENT_VALUES.indexOf(subagents) === -1 ? 'show' : subagents,
      mark_read_after: MARK_VALUES.indexOf(mark) === -1 ? 0 : mark,
      canned_replies: canned
    };
  }

  function sendToPkjs(message) {
    return new Promise((resolve, reject) => {
      if (!Pebble || typeof Pebble.sendMessage !== 'function') {
        reject(new Error('The phone app cannot deliver watch settings.'));
        return;
      }
      let result;
      try {
        result = Pebble.sendMessage('pkjs', message);
      } catch (error) {
        reject(error);
        return;
      }
      Promise.resolve(result).then(resolve, reject);
    }).then(reply => {
      if (!reply || typeof reply !== 'object') {
        throw new Error('No response from OpenCode Status.');
      }
      if (reply.error) {
        throw new Error(typeof reply.error === 'string' ? reply.error :
          reply.error.message || 'OpenCode Status rejected the settings request.');
      }
      return reply;
    });
  }

  function loadSettings() {
    if (!state.ready || state.loaded) return;
    feedback('Loading watch settings...');
    sendToPkjs({ type: 'ocstatus_settings' }).then(settings => {
      applySettings(settings);
      setLoaded(true);
      feedback('Watch settings loaded.');
    }).catch(error => {
      setLoaded(false);
      feedback(error && error.message ? error.message :
        'Watch settings are unavailable. Reopen settings from the Pebble app.', true);
    });
  }

  function saveSettings() {
    if (!state.loaded || state.saving) return;
    state.saving = true;
    setLoaded(true);
    feedback('Saving watch settings...');
    sendToPkjs({
      type: 'ocstatus_save_settings',
      settings: collectSettings()
    }).then(saved => {
      applySettings(saved);
      state.saving = false;
      setLoaded(true);
      feedback('Watch settings saved.');
    }).catch(error => {
      state.saving = false;
      setLoaded(true);
      feedback(error && error.message ? error.message : 'Watch settings were not saved.', true);
    });
  }

  function onReady(event) {
    if (state.ready) return;
    const target = event && event.target;
    if (target && target !== 'pkjs') return;
    state.ready = true;
    loadSettings();
  }

  const save = $('ocstatusSave');
  if (save) save.addEventListener('click', saveSettings);
  Pebble.addEventListener('ready', onReady);
  setLoaded(false);

  // A page script added after the bridge fired ready, or a host that has no ready replay,
  // still needs to ask for persisted settings before enabling Save.
  let earlyTargets = [];
  try {
    earlyTargets = typeof Pebble.readyTargets === 'function' ? Pebble.readyTargets() : [];
  } catch (error) {
    earlyTargets = [];
  }
  if (Array.isArray(earlyTargets) && earlyTargets.indexOf('pkjs') !== -1) {
    state.ready = true;
    loadSettings();
  }
})();
</script>`;

  let output = html.replace('</style>', css + '\n  </style>');
  output = output.replace(/([ \t]*)<p id="feedback"/, function (_, indent) {
    return section + '\n\n' + indent + '<p id="feedback"';
  });
  for (const id of ['ocstatusPreferences', 'ocstatusControls', 'ocstatusSave', 'replyAlerts']) {
    if (!new RegExp('\\bid="' + id + '"').test(output)) {
      fail('generated config page is missing required #' + id + ' control');
    }
  }
  output = output.replace('</body>', statusScript + '\n</body>');
  output = output.replace('<title>OpenCode settings</title>', '<title>OpenCode Status settings</title>');
  output = output.replace('<h1>OpenCode settings</h1>', '<h1>OpenCode Status settings</h1>');
  output = output.replace(
    /if\s*\(\s*event\.target\s*!==\s*['"]plugin['"]\s*\|\|\s*state\.ready\s*\)\s*return;/,
    "var readyTarget = event && event.target;\n    if ((readyTarget && readyTarget !== 'plugin') || state.ready) return;"
  );
  output = output.replace(/^(<!doctype html>\s*)/i, '$1' + GENERATED_NOTE + '\n');
  return output.replace(/[\t ]+$/gm, '');
}

function main() {
  const args = process.argv.slice(2);
  const check = args.includes('--check');
  const sourceArg = args.find(argument => argument !== '--check');
  const sourceRoot = sourceArg ? path.resolve(process.cwd(), sourceArg) : DEFAULT_SOURCE;

  const sourcePackageFile = path.join(sourceRoot, 'package.json');
  const targetPackageFile = path.join(ROOT, 'package.json');
  const sourcePackage = readJson(sourcePackageFile, 'source package.json');
  const targetPackage = readJson(targetPackageFile, 'target package.json');

  const sourcePebble = sourcePackage.pebble;
  if (!sourcePebble || !sourcePebble.plugin || typeof sourcePebble.plugin !== 'object') {
    fail('source package has no pebble.plugin block');
  }
  if (!isUuid(sourcePebble.uuid)) fail('source pebble.uuid is not a valid UUID');
  if (!isUuid(targetPackage.pebble.uuid)) fail('target pebble.uuid is not a valid UUID');
  if (!Array.isArray(sourcePebble.plugin.sources) || !sourcePebble.plugin.sources.length) {
    fail('source pebble.plugin.sources is empty');
  }
  if (!Array.isArray(sourcePebble.plugin.actions) || !sourcePebble.plugin.actions.length) {
    fail('source pebble.plugin.actions is empty');
  }

  const sourceScript = projectFile(
    sourcePebble.plugin.script || 'plugin.js', 'source plugin script', sourceRoot);
  const sourceConfig = projectFile(
    typeof sourcePebble.configPage === 'string' && !/^https?:/.test(sourcePebble.configPage)
      ? sourcePebble.configPage : 'src/config.html',
    'source config page',
    sourceRoot
  );
  const scriptText = readText(sourceScript, 'source plugin script');
  const configText = readText(sourceConfig, 'source config page');

  const generatedScript = scriptText.startsWith(BUNDLE_MARKER)
    ? scriptText : BUNDLE_MARKER + scriptText;
  const generatedConfig = injectStatusSettings(configText);

  const nextPackage = clone(targetPackage);
  const plugin = clone(sourcePebble.plugin);
  plugin.script = PLUGIN_SCRIPT;
  nextPackage.pebble.plugin = plugin;
  nextPackage.pebble.configPage = CONFIG_PAGE;
  nextPackage.pebble.messageKeys = Array.isArray(nextPackage.pebble.messageKeys)
    ? nextPackage.pebble.messageKeys : [];
  if (nextPackage.pebble.messageKeys.indexOf('open_reply') === -1) {
    nextPackage.pebble.messageKeys.push('open_reply');
  }
  nextPackage.pebble.usesPermissions = copiedPermissions(targetPackage, sourcePackage);

  const outputs = [
    [projectFile(PLUGIN_SCRIPT, 'plugin script'), generatedScript],
    [projectFile(CONFIG_PAGE, 'config page'), generatedConfig],
    [targetPackageFile, JSON.stringify(nextPackage, null, 2) + '\n']
  ];

  let stale = false;
  for (const [file, content] of outputs) {
    let current = null;
    try {
      current = fs.readFileSync(file, 'utf8');
    } catch (error) {
      current = null;
    }
    if (current !== content) {
      stale = true;
      if (!check) {
        fs.mkdirSync(path.dirname(file), { recursive: true });
        fs.writeFileSync(file, content);
      }
    }
    const relative = path.relative(ROOT, file);
    console.log((check ? (current === content ? 'current ' : 'stale   ') : 'wrote   ') + relative);
  }

  if (check && stale) fail('generated assets are stale; run node scripts/sync-plugin.js');
}

main();
